import { readFileSync } from 'node:fs'
import path from 'node:path'
import { expect, test } from '@playwright/test'

// Real backend DANFE HTML generated by the unit test. These are synthetic
// documents and not SEFAZ-authorized invoices. The fixture directory is
// intentionally opt-in; normal frontend CI never needs Go or a certificate.
const fixtureDir = process.env.DANFE_TEST_BROWSER_DIR
test.skip(!fixtureDir, 'requires Go-generated synthetic DANFE fixtures')

for (const width of [58, 80] as const) {
  test(`DANFE thermal print layout ${width} mm: no clipping, QR and readable products`, async ({ page }) => {
    const markup = readFileSync(path.join(fixtureDir!, `danfe-${width}.html`), 'utf8')
    await page.setViewportSize({ width: width === 58 ? 236 : 340, height: 900 })
    await page.emulateMedia({ media: 'print' })
    await page.setContent(markup, { waitUntil: 'load' })

    await expect(page.locator('body')).toHaveClass(`receipt-${width}`)
    await expect(page.locator('.items-table .item-desc')).toContainText('Produto & teste')
    await expect(page.locator('.key')).toBeVisible()
    await expect(page.locator('.qr img')).toBeVisible()
    await expect(page.getByText(/HOMOLOGAÇÃO/)).toBeVisible()

    const metrics = await page.evaluate(() => {
      const body = document.body
      const doc = document.documentElement
      const table = document.querySelector('.items-table')!
      const qr = document.querySelector('.qr img')!
      const item = document.querySelector('.items-table .item-desc')!
      const css = getComputedStyle(table)
      const bodyRect = body.getBoundingClientRect()
      const tableRect = table.getBoundingClientRect()
      const qrRect = qr.getBoundingClientRect()
      const itemRect = item.getBoundingClientRect()
      return {
        scrollWidth: doc.scrollWidth,
        viewportWidth: window.innerWidth,
        bodyWidth: bodyRect.width,
        tableWidth: tableRect.width,
        qrWidth: qrRect.width,
        qrFits: qrRect.left >= bodyRect.left - 1 &&
          qrRect.right <= bodyRect.right + 1,
        descriptionFits: itemRect.left >= tableRect.left - 1 &&
          itemRect.right <= tableRect.right + 1,
        tableDisplay: css.display,
      }
    })

    const expectedPx = width * 96 / 25.4
    expect(metrics.scrollWidth).toBeLessThanOrEqual(metrics.viewportWidth + 1)
    expect(metrics.bodyWidth).toBeLessThanOrEqual(expectedPx + 1)
    expect(metrics.tableWidth).toBeLessThanOrEqual(expectedPx + 1)
    expect(metrics.qrWidth).toBeGreaterThan(115)
    expect(metrics.qrWidth).toBeLessThan(125)
    expect(metrics.qrFits).toBe(true)
    expect(metrics.descriptionFits).toBe(true)
    expect(metrics.tableDisplay).toBe(width === 58 ? 'block' : 'table')
  })
}
